class Stock:
    def __init__(self, quantity):
        if type(quantity) is not int or quantity < 0:
            raise ValueError("invalid initial quantity")
        self._quantity = quantity

    @property
    def quantity(self):
        return self._quantity

    def withdraw(self, amount):
        if type(amount) is not int or amount <= 0:
            raise ValueError("invalid amount")
        if amount > self._quantity:
            raise ValueError("not enough stock")
        self._quantity -= amount

stock = Stock(3)
for amount in (4, 0, 3):
    try:
        stock.withdraw(amount)
    except ValueError:
        print("rejected")
    print(stock.quantity)

class DeskCounter:
    def __init__(self):
        self._available = 0

    @property
    def available(self):
        return self._available

    def return_desk(self):
        self._available += 1

desks = DeskCounter()
try:
    desks.available = -1
except AttributeError:
    print("read-only")
desks.return_desk()
print(desks.available)

class Line:
    def __init__(self):
        self._quantity = 0

    def receive(self, amount):
        if type(amount) is not int or amount <= 0:
            raise ValueError("invalid amount")
        self._quantity += amount

    @property
    def quantity(self):
        return self._quantity

class Inventory:
    def __init__(self):
        self._lines = {}

    def register(self, sku):
        if sku in self._lines:
            raise ValueError("duplicate SKU")
        self._lines[sku] = Line()

    def receive(self, sku, amount):
        self._lines[sku].receive(amount)

    def quantity(self, sku):
        return self._lines[sku].quantity

stock = Inventory()
stock.register("PEN")
stock.register("NOTE")
stock.receive("PEN", 4)
print(stock.quantity("PEN"))
print(stock.quantity("NOTE"))

class Edge:
