        self.centimeters = centimeters

class Label:
    def __init__(self, width, height):
        self._width = width
        self._height = height

    def area(self):
        return self._width.centimeters * self._height.centimeters

width = Edge(4)
height = Edge(3)
label = Label(width, height)
print(label.area())
width.centimeters = 5
print(label.area())

from dataclasses import FrozenInstanceError, dataclass

@dataclass(frozen=True)
class ProductSpec:
    sku: str
    unit_price: int

first = ProductSpec("PEN", 125)
second = ProductSpec("PEN", 125)
print(first == second)
print(first is second)
try:
    first.unit_price = 200
except FrozenInstanceError:
    print(first.unit_price)

class Label:
    def label(self, sku):
        return f"SKU {sku}"

class PriorityLabel(Label):
    def label(self, sku):
        return "PRIORITY " + super().label(sku)

def show_label(formatter, sku):
    print(formatter.label(sku))

show_label(Label(), "PEN")
show_label(PriorityLabel(), "PEN")

class FixedCharge:
    def quote(self, boxes):
        return 300

class PerBoxCharge:
    def quote(self, boxes):
        return boxes * 125

def show_quote(policy, boxes):
    print(policy.quote(boxes))

show_quote(FixedCharge(), 4)
show_quote(PerBoxCharge(), 4)

