class Stock:
    def __init__(self, fault):
        self._quantity = 3
        self._fault = fault

    @property
    def quantity(self):
        return self._quantity

    def withdraw(self, amount):
        if self._fault == "boundary" and amount == self._quantity:
            raise ValueError("incorrect boundary")
        if amount > self._quantity:
            if self._fault == "ignored":
                return
            if self._fault == "premature":
                self._quantity -= amount
            raise ValueError("not enough stock")
        self._quantity -= amount

def check_withdraw(make_stock):
    exact = make_stock()
    try:
        exact.withdraw(3)
    except ValueError:
        return False
    if exact.quantity != 0:
        return False

    overdraw = make_stock()
    try:
        overdraw.withdraw(4)
    except ValueError:
        return overdraw.quantity == 3
    return False

selected = input().strip()

def make_stock():
    return Stock(selected)

print("pass" if check_withdraw(make_stock) else "fail")
